import React, { useState, useEffect } from 'react';
import './CSS/Orders.css';

const Orders = () => {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);

  // Fetch orders from your backend API
  useEffect(() => {
    fetch('http://localhost:4000/api/seller/orders')
      .then(res => res.json())
      .then(data => {
        setOrders(data);
        setLoading(false);
      })
      .catch(err => {
        console.error('Error fetching orders:', err);
        // Fallback sample data if API fails or isn't set up yet
        setOrders([
          {
            _id: 'HEX-78492',
            createdAt: '2026-06-12',
            totalAmount: 52098,
            status: 'Delivered',
            items: [
              { title: 'Redmi 17 pro', quantity: 1, price: 49999 },
              { title: 'Smart watch', quantity: 1, price: 2099 }
            ]
          },
          {
            _id: 'HEX-78510',
            createdAt: '2026-06-20',
            totalAmount: 2099,
            status: 'Processing',
            items: [
              { title: 'Smart watch', quantity: 1, price: 2099 }
            ]
          }
        ]);
        setLoading(false);
      });
  }, []);

  if (loading) {
    return (
      <div className="orders-page">
        <div className="orders-header">
          <h1>My Orders</h1>
          <p>Loading your purchase history...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="orders-page">
      <div className="orders-header">
        <span className="orders-tag">PURCHASE HISTORY</span>
        <h1>My Orders</h1>
        <p>Track, manage, and view the status of your past orders.</p>
      </div>

      {orders.length === 0 ? (
        <div className="empty-orders">
          <p>You haven't placed any orders yet.</p>
          <a href="/products" className="orders-btn-primary">Start Shopping</a>
        </div>
      ) : (
        <div className="orders-list">
          {orders.map(order => (
            <div className="order-card" key={order._id || order.orderId}>
              <div className="order-card-header">
                <div>
                  <span className="order-id-label">Order ID: </span>
                  <strong>{order._id || order.orderId}</strong>
                  <span className="order-date"> • Placed on {order.createdAt?.slice(0, 10) || 'Recent'}</span>
                </div>
                <span className={`order-status ${(order.status || 'Processing').toLowerCase()}`}>
                  {order.status || 'Processing'}
                </span>
              </div>

              <div className="order-card-body">
                {order.items?.map((item, idx) => (
                  <div className="order-item-row" key={idx}>
                    <span>{item.title} (x{item.quantity})</span>
                    <span>₹{(item.price * item.quantity).toLocaleString()}</span>
                  </div>
                ))}
              </div>

              <div className="order-card-footer">
                <div className="order-total">
                  <span>Total Amount:</span>
                  <strong>₹{(order.totalAmount || order.total || 0).toLocaleString()}</strong>
                </div>
                <button className="order-track-btn">View Details</button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default Orders;
